def needs_retrieval(query):
    # decide whether retrieval is needed at all
    small_talk = ["hello", "thanks", "how are you"]
    return not any(phrase in query.lower() for phrase in small_talk)

def reflect_on_passage_relevance(passage, query_terms):
    # critique each retrieved passage for relevance
    overlap = sum(1 for term in query_terms if term in passage.lower())
    return "relevant" if overlap >= 1 else "irrelevant"

def reflect_on_answer_support(answer, passage):
    # critique whether the answer is supported by the passage
    return "supported" if any(word in passage.lower() for word in answer.lower().split()) else "unsupported"

def self_rag(query, passages):
    if not needs_retrieval(query):
        return {"retrieval": "skipped", "answer": "Hello! Happy to help."}

    query_terms = query.lower().split()
    relevant_passages = [p for p in passages if reflect_on_passage_relevance(p, query_terms) == "relevant"]

    answer = f"Simulated answer grounded in: {relevant_passages[0]}" if relevant_passages else "No relevant passage found."
    support = reflect_on_answer_support(answer, relevant_passages[0] if relevant_passages else "")

    return {"retrieval": "used", "relevant_passages": relevant_passages, "answer": answer, "support": support}

passages = ["The Falcon plan costs twenty dollars per month."]
print("Self-RAG on a factual query:")
print(self_rag("What does the Falcon plan cost?", passages))

print("\nSelf-RAG on small talk, where retrieval is skipped:")
print(self_rag("hello there", passages))
